(() => {
  window.fails = []; window.must = (ok, info) => { if (!ok) fails.push(info); return { ok, info }; };
  window.tidy = () => { const w = mc.theWorld; w.worldInfo.gameRules.doMobSpawning = false; for (const e of w.loadedEntityList) if (e !== mc.thePlayer) e.setDead(); mc.dev.ticks(1); };
  window.heardReset = () => { mc.sndManager.debugLog.length = 0; };
  window.heard = (re) => mc.sndManager.debugLog.filter((e) => e.kind === 'requested' && (typeof re === 'string' ? e.name === re : re.test(e.name))).length;
  window.names = () => mc.sndManager.debugLog.filter((e) => e.kind === 'requested').map((e) => e.name);
  // Counts calls of an entity method (the sound's source event) without changing what it does.
  window.countCalls = (obj, method) => { const c = { n: 0 }; const orig = obj[method]; obj[method] = function (...a) { c.n++; return orig.apply(this, a); }; return c; };
  window.home = () => { mc.dev.tp(8.5, 4, 8.5, 180, 0); mc.thePlayer.motionX = mc.thePlayer.motionY = mc.thePlayer.motionZ = 0; mc.dev.ticks(1); };
  tidy();
  return { audio: mc.sndManager.getDebugInfo(), state: mc.dev.survival.state().mode };
})()

(() => {
  const p = mc.thePlayer, w = mc.theWorld, L = mc.dev.lib;
  const out = {};
  home();
  mc.dev.setStack(0, 1, 64); mc.dev.setStack(1, 278, 1); mc.dev.select(0);
  // Place a stone block on the ground two blocks north, then mine it and walk onto the drop.
  mc.dev.look(180, 45); mc.dev.ticks(2);
  heardReset(); mc.dev.click(1); mc.dev.ticks(2); out.place = names();
  must(heard('dig.stone') === 1 && names().length === 1, { place: out.place });
  mc.dev.select(1); mc.dev.ticks(1);
  heardReset(); mc.dev.mouse(0, true);
  let t = 0; while (mc.dev.target() === 1 && t++ < 60) mc.dev.ticks(1);
  mc.dev.mouse(0, false); mc.dev.ticks(1);
  out.mine = names(); out.mineTicks = t;
  must(heard('dig.stone') === 1 && heard(/^dig\./) === 1, { mine: out.mine });
  heardReset();
  const drop = mc.dev.entities('Item')[0];
  if (drop) { mc.dev.tp(drop.posX, 4, drop.posZ, 180, 0); mc.dev.ticks(20); }
  out.pickup = names();
  must(!!drop && heard('random.pop') === 1, { pickup: out.pickup, drop: !!drop });
  home();
  // Walk north for 30 ticks: one step sound per step.
  const steps = countCalls(p, 'playStepSound');
  heardReset(); mc.dev.press(17, 30); mc.dev.ticks(5);
  out.walk = { steps: steps.n, heard: heard(/^step\./) };
  must(steps.n >= 3 && heard(/^step\./) === steps.n, { walk: out.walk });
  home();
  return out;
})()

